// SPDX-License-Identifier: MIT AND Apache-2.0
pragma solidity 0.8.23;

import { ExecutionLib } from "./lib/ExecutionLib.sol";

import { CaveatEnforcer } from "./CaveatEnforcer.sol";
import { ModeCode } from "./utils/Types.sol";

/**
 * @title AllowedTargetsEnforcer
 * @dev This contract enforces the allowed target addresses for a delegate.
 * @dev This enforcer operates only in single execution call type and with default execution mode.
 */
contract AllowedTargetsEnforcer is CaveatEnforcer {
    using ExecutionLib for bytes;

    ////////////////////////////// Public Methods //////////////////////////////

    /**
     * @notice Allows the delegator to limit what addresses the delegate may call.
     * @dev This function enforces the allowed target addresses before the transaction is performed.
     * @param _terms A series of 20byte addresses, representing the addresses that the delegate is allowed to call.
     * @param _mode The execution mode. (Must be Single callType, Default execType)
     * @param _executionCallData The execution the delegate is trying try to execute.
     */
    function beforeHook(
        bytes calldata _terms,
        bytes calldata,
        ModeCode _mode,
        bytes calldata _executionCallData,
        bytes32,
        address,
        address
    )
        public
        pure
        override
        onlySingleCallTypeMode(_mode)
        onlyDefaultExecutionMode(_mode)
    {
        (address target_,,) = _executionCallData.decodeSingle();

        address[] memory allowedTargets_ = getTermsInfo(_terms);
        uint256 allowedTargetsLength_ = allowedTargets_.length;
        for (uint256 i = 0; i < allowedTargetsLength_; ++i) {
            if (target_ == allowedTargets_[i]) {
                return;
            }
        }
        revert("AllowedTargetsEnforcer:target-address-not-allowed");
    }

    /**
     * @notice Decodes the terms used in this CaveatEnforcer.
     * @param _terms encoded data that is used during the execution hooks.
     * @return allowedTargets_ The allowed target addresses.
     */
    function getTermsInfo(bytes calldata _terms) public pure returns (address[] memory allowedTargets_) {
        uint256 j = 0;
        uint256 termsLength_ = _terms.length;
        require(termsLength_ % 20 == 0 && termsLength_ != 0, "AllowedTargetsEnforcer:invalid-terms-length");
        allowedTargets_ = new address[](termsLength_ / 20);
        for (uint256 i = 0; i < termsLength_; i += 20) {
            allowedTargets_[j] = address(bytes20(_terms[i:i + 20]));
            j++;
        }
    }
}

contracts/CaveatEnforcer.sol.content:
// SPDX-License-Identifier: MIT AND Apache-2.0
pragma solidity 0.8.23;

import { ModeLib } from "./lib/ModeLib.sol";

import { ICaveatEnforcer } from "./interfaces/ICaveatEnforcer.sol";
import { ModeCode, ExecType } from "./utils/Types.sol";
import { CALLTYPE_SINGLE, CALLTYPE_BATCH, EXECTYPE_DEFAULT, EXECTYPE_TRY } from "./utils/Constants.sol";

/**
 * @title CaveatEnforcer
 * @dev This abstract contract enforces caveats before and after the execution of an execution.
 */
abstract contract CaveatEnforcer is ICaveatEnforcer {
    using ModeLib for ModeCode;

    /// @inheritdoc ICaveatEnforcer
    function beforeAllHook(bytes calldata, bytes calldata, ModeCode, bytes calldata, bytes32, address, address) public virtual { }

    /// @inheritdoc ICaveatEnforcer
    function beforeHook(bytes calldata, bytes calldata, ModeCode, bytes calldata, bytes32, address, address) public virtual { }

    /// @inheritdoc ICaveatEnforcer
    function afterHook(bytes calldata, bytes calldata, ModeCode, bytes calldata, bytes32, address, address) public virtual { }

    /// @inheritdoc ICaveatEnforcer
    function afterAllHook(bytes calldata, bytes calldata, ModeCode, bytes calldata, bytes32, address, address) public virtual { }

    /**
     * @dev Require the function call to be in single call type
     */
    modifier onlySingleCallTypeMode(ModeCode _mode) {
        {
            require(ModeLib.getCallType(_mode) == CALLTYPE_SINGLE, "CaveatEnforcer:invalid-call-type");
        }
        _;
    }

    /**
     * @dev Require the function call to be in batch call type
     */
    modifier onlyBatchCallTypeMode(ModeCode _mode) {
        {
            require(ModeLib.getCallType(_mode) == CALLTYPE_BATCH, "CaveatEnforcer:invalid-call-type");
        }
        _;
    }

    /**
     * @dev Require the function call to be in default execution mode
     */
    modifier onlyDefaultExecutionMode(ModeCode _mode) {
        {
            (, ExecType _execType,,) = _mode.decode();
            require(_execType == EXECTYPE_DEFAULT, "CaveatEnforcer:invalid-execution-type");
        }
        _;
    }

    /**
     * @dev Require the function call to be in try execution mode
     */
    modifier onlyTryExecutionMode(ModeCode _mode) {
        {
            (, ExecType _execType,,) = _mode.decode();
            require(_execType == EXECTYPE_TRY, "CaveatEnforcer:invalid-execution-type");
        }
        _;
    }
}

